ruleContent.content:
@js:(function(){
  var j = null;
  var s = String(result);
  try { j = JSON.parse(s); } catch(e){ j = result; }
  if (!j || !j.data) return '';
  var su = j.data.streamURL || [];
  for (var i=0;i<su.length;i++){
    if (su[i].status===1 && !su[i].onlyVIP && su[i].stream) return su[i].stream;
  }
  if (su.length) return su[0].stream;
  return '';
})()

ruleExplore.bookList:
@js:(function(){
  var j = null;
  var s = String(result);
  try { j = JSON.parse(s); } catch(e){ j = result; }
  if (!j || !j.data) return [];
  var d = j.data;
  if (d.listSong) return d.listSong;
  if (d.length !== undefined && d.length !== null) return d;
  return [];
})()

ruleToc.chapterList:
@js:(function(){
  var j = null;
  var s = String(result);
  try { j = JSON.parse(s); } catch(e){ j = result; }
  if (!j || !j.data) return [];
  var d = j.data;
  if (d.streamURL){
    var k = d.key || '';
    if (!k) return [];
    return [{name:(d.name||'Track')+(d.artistName?' - '+d.artistName:''), url:'https://graph.nct.vn/api/v1/song/detail/'+k}];
  }
  var list = d.listSong || d.items || [];
  var out = [];
  var seen = {};
  for (var i=0;i<list.length;i++){
    var it = list[i] || {};
    var k2 = it.key || '';
    if (!k2 || seen[k2]) continue;
    seen[k2] = 1;
    var nm = it.name || ('Track '+(i+1));
    var ar = it.artistName || '';
    out.push({name:(i+1)+'. '+nm+(ar?' - '+ar:''), url:'https://graph.nct.vn/api/v1/song/detail/'+k2});
  }
  return out;
})()
